// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(this)); }
    function testRegression_property() public {
        c.endConfiguration();
        vm.warp(1000);
        c.endConfiguration();
        address evil = address(0xDEAD);
        vm.startPrank(evil);
        (bool ok,) = address(c).call(abi.encodeWithSignature("setDAO(address)", address(0xBEEF)));
        vm.stopPrank();
        vm.prank(address(this));
        try c.assertGovernanceApproved(address(this), address(this), false) {} catch {}
        assertTrue(c.DAO() == address(this));
    }
}
